css:
.valuesim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #e6edf3;
    background: linear-gradient(160deg, #0d1b24 0%, #111f2c 55%, #0b2733 100%);
    border-radius: 18px;
}

.valuesim-container * {
    box-sizing: border-box;
}

.valuesim-header {
    text-align: center;
    padding: 26px 20px 22px;
    background: linear-gradient(135deg, #0a2a3a 0%, #0e4154 55%, #1f8f8a 100%);
    color: #f1fbfb;
    border-radius: 16px;
    margin-bottom: 20px;
    box-shadow: 0 12px 34px rgba(0, 0, 0, 0.45);
    border: 1px solid rgba(60, 220, 200, 0.14);
}

.valuesim-header h1 {
    margin: 8px 0 10px;
    font-size: 2.3rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    color: #f5fffe;
}

.valuesim-header-tag {
    display: inline-block;
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #7ff0e0;
    background: rgba(0, 0, 0, 0.28);
    padding: 5px 14px;
    border-radius: 999px;
}

.valuesim-subtitle {
    margin: 0 auto;
    max-width: 800px;
    font-size: 0.98rem;
    line-height: 1.55;
    color: #cfeeec;
}

.valuesim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #9fc4cf;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.valuesim-period-counter #currentDay,
.valuesim-period-counter #maxPeriods {
    font-weight: 800;
    color: #45e3c8;
}

.valuesim-round-name {
    background: rgba(69, 227, 200, 0.14);
    color: #6cf2da;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
    border: 1px solid rgba(69, 227, 200, 0.25);
}

.valuesim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #ffb27a;
    background: rgba(255, 122, 60, 0.14);
    padding: 4px 12px;
    border-radius: 999px;
    border: 1px solid rgba(255, 122, 60, 0.28);
}

.valuesim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.valuesim-status-card {
    background: #11222e;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #1d3441;
    box-shadow: 0 6px 18px rgba(0, 0, 0, 0.30);
    border-top: 4px solid #1f8f8a;
}

.valuesim-card-value { border-top-color: #2fd49b; }
.valuesim-card-defense { border-top-color: #3aa0e0; }
.valuesim-card-roi { border-top-color: #b58cf0; }
.valuesim-card-speed { border-top-color: #e0a93a; }

.valuesim-label {
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #7d9aa6;
}

.valuesim-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #e6edf3;
}

.valuesim-card-value .valuesim-value { color: #2fd49b; }
.valuesim-card-defense .valuesim-value { color: #5cb6ee; }
.valuesim-card-roi .valuesim-value { color: #c2a3f5; }
.valuesim-card-speed .valuesim-value { color: #efbf5e; }

.valuesim-sublabel {
    font-size: 0.75rem;
    color: #6f8b97;
    line-height: 1.35;
}

.valuesim-value-fail .valuesim-value { color: #ff6b5e; }
.valuesim-value-target .valuesim-value { color: #2fd49b; }

.valuesim-speed-late { border-top-color: #ff6b5e; }
.valuesim-speed-late .valuesim-value { color: #ff6b5e; }
.valuesim-speed-fast { border-top-color: #2fd49b; }

.valuesim-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #08313a;
    color: #d6f5f1;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
    border: 1px solid #15414b;
}

.valuesim-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #6cf2da;
}

.valuesim-budget-over #budgetDisplay {
    color: #ff6b5e;
}

.valuesim-briefing {
    display: flex;
    gap: 14px;
    background: #11222e;
    border-left: 5px solid #1f8f8a;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(0, 0, 0, 0.28);
}

.valuesim-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.valuesim-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #6cf2da;
    margin-bottom: 6px;
}

.valuesim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #cdddE5;
}

.valuesim-briefing-text strong { color: #2fd49b; }
.valuesim-briefing-text em { color: #ffb27a; font-style: italic; }

.valuesim-controls {
    background: #11222e;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #1d3441;
    box-shadow: 0 6px 18px rgba(0, 0, 0, 0.28);
}

.valuesim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #e6edf3;
    border-bottom: 2px solid #1d3441;
    padding-bottom: 8px;
}

.valuesim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #b6cdd6;
    margin: 14px 0 6px;
}

.valuesim-container select,
.valuesim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #2a4654;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #0d1e28;
    color: #e6edf3;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.valuesim-container select:focus,
.valuesim-container input[type="number"]:focus {
    outline: none;
    border-color: #2fd49b;
    box-shadow: 0 0 0 3px rgba(47, 212, 155, 0.18);
}

.valuesim-container select option {
    background-color: #0d1e28;
    color: #e6edf3;
}

.valuesim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #2fd49b;
}

.valuesim-range-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #8fc7cf;
    margin-top: 4px;
}

.valuesim-range-readout span:last-child {
    color: #2fd49b;
    font-weight: 800;
}

.valuesim-hint {
    font-size: 0.8rem;
    color: #6f8b97;
    margin-top: 4px;
    line-height: 1.4;
}

.valuesim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.valuesim-container .btn-primary {
    background: linear-gradient(135deg, #1f8f8a 0%, #2fd49b 100%);
    border: none;
    color: #04221d;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 8px 20px rgba(47, 212, 155, 0.26);
}

.valuesim-container .btn-primary:hover {
    filter: brightness(1.08);
}

.valuesim-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #2a4654;
    color: #8fa9b4;
    background: transparent;
}

.valuesim-coach {
    background: #08313a;
    color: #d6f5f1;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 8px 22px rgba(0, 0, 0, 0.32);
    border: 1px solid #15414b;
}

.valuesim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #5cd9c5;
    margin-bottom: 8px;
}

.valuesim-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.valuesim-coach-body strong { color: #6cf2da; }
.valuesim-coach-body em { color: #ffc69e; font-style: italic; }

.valuesim-history,
.valuesim-chart {
    background: #11222e;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #1d3441;
    box-shadow: 0 6px 18px rgba(0, 0, 0, 0.28);
}

.valuesim-history h3,
.valuesim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #e6edf3;
}

.valuesim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #cdddE5;
}

.valuesim-container table#usfHistoryTable th {
    background: #0d1e28;
    color: #6cf2da;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #1d3441;
}

.valuesim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #19303b;
}

.valuesim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #0f1f2a;
}

.valuesim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .valuesim-container {
        padding: 14px;
    }
    .valuesim-header h1 {
        font-size: 1.7rem;
    }
    .valuesim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .valuesim-value {
        font-size: 2rem;
    }
    .valuesim-clock {
        margin-left: 0;
    }
    .valuesim-period-counter {
        font-size: 0.88rem;
    }
    .valuesim-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .valuesim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* v1.1.0 completion message (formatCompletionMessage) — self-contained, readable on the white modal */
.valuesim-completion { font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; color: #142033; }
.valuesim-cm-head { display: flex; align-items: center; gap: 18px; flex-wrap: wrap; padding-bottom: 14px; border-bottom: 1px solid rgba(20,32,51,0.15); margin-bottom: 16px; }
.valuesim-cm-score { font-size: 46px; font-weight: 800; line-height: 1; color: #1f7a55; }
.valuesim-cm-score-max { font-size: 18px; font-weight: 600; color: #44597a; margin-left: 2px; }
.valuesim-cm-grade { font-size: 18px; font-weight: 700; color: #142033; display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
.valuesim-cm-badge { display: inline-block; font-size: 12px; font-weight: 700; letter-spacing: .02em; padding: 3px 10px; border-radius: 999px; }
.valuesim-cm-yes { background: rgba(31,122,85,0.15); color: #175d40; }
.valuesim-cm-no { background: rgba(176,51,37,0.12); color: #b03325; }
.valuesim-cm-warn { background: rgba(180,110,20,0.16); color: #8a5410; }
.valuesim-cm-metrics { display: flex; gap: 12px; flex-wrap: wrap; margin-bottom: 18px; }
.valuesim-cm-metric { flex: 1 1 120px; background: #eef1f6; border: 1px solid rgba(20,32,51,0.10); border-radius: 10px; padding: 12px 14px; text-align: center; }
.valuesim-cm-mv { display: block; font-size: 22px; font-weight: 800; color: #142033; }
.valuesim-cm-ml { display: block; font-size: 12px; font-weight: 600; color: #44597a; margin-top: 2px; }
.valuesim-cm-insights-title { font-size: 14px; font-weight: 700; text-transform: uppercase; letter-spacing: .04em; color: #44597a; margin-bottom: 8px; }
.valuesim-cm-insights { margin: 0; padding-left: 20px; }
.valuesim-cm-insights li { font-size: 14px; line-height: 1.5; color: #22314a; margin-bottom: 8px; }

