(function() {
    'use strict';

    class ValueCaptureAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Capturing the Value`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (Veridian Systems SAS).
            this.START_VALUE = 18;       // captures little recurring value today
            this.START_DEFENSE = 12;     // analytics models unprotected
            this.START_ROI = 20;
            this.TARGET_VALUE = 70;      // board-credible value-capture share
            this.BUDGET_CAP = 40;        // EUR 40M two-year envelope
            this.IMITATION_WINDOW = 9;   // 6-9 months to copy the analytics

            // Concept truths.
            this.TRUE_LAYER = `datalayer`;
            this.TRUE_EXPOSED = `analytics`;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    value: this.START_VALUE,
                    defense: this.START_DEFENSE,
                    roi: this.START_ROI,
                    speed: 0,            // months-to-market, set in round 2 (0 = not yet sourced)
                    budgetUsed: 0,
                    revShare: 0,         // % of upside ceded (partner path)
                    baseLost: false,     // installed base locked to PlantSense
                    overBudget: false,
                    cededData: false,
                    valueHistory: [this.START_VALUE],
                    defenseHistory: [this.START_DEFENSE],
                    roiHistory: [this.START_ROI],
                    coachMessages: [],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    layer: `datalayer`,
                    exposed: `analytics`,
                    clarity: 60,
                    source: `buy`,
                    focus: `datalayer`,
                    interim: 4,
                    model: `outcome`,
                    moat: `datamoat`,
                    defense: 8,
                    align: 60,
                    gtm: `fast`,
                    roiDefence: `adjusted`,
                    answer: `moat`,
                    conviction: 70
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const layer = document.getElementById(`layerInput`);
                const exposed = document.getElementById(`exposedInput`);
                const clar = document.getElementById(`clarityInput`);
                if (layer) decisions.layer = layer.value;
                if (exposed) decisions.exposed = exposed.value;
                if (clar) decisions.clarity = parseInt(clar.value, 10);
                if (!Number.isFinite(decisions.clarity) || decisions.clarity < 0 || decisions.clarity > 100) {
                    warn(`warn_clarity_range`); return false;
                }
            } else if (round === 2) {
                const src = document.getElementById(`sourceInput`);
                const foc = document.getElementById(`focusInput`);
                const intm = document.getElementById(`interimInput`);
                if (src) decisions.source = src.value;
                if (foc) decisions.focus = foc.value;
                if (intm) decisions.interim = parseFloat(intm.value);
                if (!Number.isFinite(decisions.interim) || decisions.interim < 0 || decisions.interim > 8) {
                    warn(`warn_interim_range`); return false;
                }
                // Envelope guard: sourcing cost + interim must fit the EUR 40M cap.
                const srcCost = this._sourceCost(decisions.source);
                if (srcCost + decisions.interim > this.BUDGET_CAP + 0.001) {
                    warn(`warn_budget_r2`); return false;
                }
            } else if (round === 3) {
                const mdl = document.getElementById(`modelInput`);
                const mt = document.getElementById(`moatInput`);
                const def = document.getElementById(`defenseInput`);
                const al = document.getElementById(`alignInput`);
                if (mdl) decisions.model = mdl.value;
                if (mt) decisions.moat = mt.value;
                if (def) decisions.defense = parseFloat(def.value);
                if (al) decisions.align = parseInt(al.value, 10);
                if (!Number.isFinite(decisions.defense) || decisions.defense < 0 || decisions.defense > 14) {
                    warn(`warn_defense_range`); return false;
                }
                if (!Number.isFinite(decisions.align) || decisions.align < 0 || decisions.align > 100) {
                    warn(`warn_align_range`); return false;
                }
                // Envelope guard: committing this defensive spend cannot exceed the EUR 40M cap.
                const ds = state.domainState;
                if (ds.budgetUsed + decisions.defense > this.BUDGET_CAP + 0.001) {
                    warn(`warn_budget_r3`); return false;
                }
            } else if (round === 4) {
                const g = document.getElementById(`gtmInput`);
                const r = document.getElementById(`roiInput`);
                const a = document.getElementById(`answerInput`);
                const cv = document.getElementById(`convictionInput`);
                if (g) decisions.gtm = g.value;
                if (r) decisions.roiDefence = r.value;
                if (a) decisions.answer = a.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        _sourceCost(src) {
            if (src === `build`) return 32;
            if (src === `buy`) return 28;
            if (src === `partner`) return 9;
            return 0;
        }

        _sourceSpeed(src) {
            if (src === `build`) return 18;
            if (src === `buy`) return 9;
            if (src === `partner`) return 5;
            return 12;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let valueDelta = 0, defenseDelta = 0, roiDelta = 0;
            let spend = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Diagnose where value is captured (Common Error 1: innovating where you are comfortable).
                if (d.layer === this.TRUE_LAYER) {
                    valueDelta += 14; roiDelta += 8; coachKey = `coach_r1_layer_right`;
                } else if (d.layer === `hardware`) {
                    valueDelta -= 10; roiDelta -= 6; coachKey = `coach_r1_hardware`;
                } else if (d.layer === `connectivity`) {
                    valueDelta -= 2; coachKey = `coach_r1_connectivity`;
                } else {
                    valueDelta -= 8; roiDelta -= 4; coachKey = `coach_r1_nowhere`;
                }

                // Spot the weak appropriability regime (analytics models, copyable in 6-9 months).
                if (d.exposed === this.TRUE_EXPOSED) {
                    defenseDelta += 12; roiDelta += 4;
                    if (d.layer === this.TRUE_LAYER) coachKey = `coach_r1_diag_sharp`;
                } else if (d.exposed === `hardware`) {
                    defenseDelta -= 8; coachKey = `coach_r1_exp_hardware`;
                } else if (d.exposed === `brand`) {
                    defenseDelta -= 4;
                } else {
                    valueDelta -= 10; defenseDelta -= 8; coachKey = `coach_r1_exp_none`;
                }

                // Clarity of the create-vs-capture distinction (the simulation's spine).
                if (d.clarity >= 60) { valueDelta += 8; roiDelta += 3; }
                else if (d.clarity <= 25) { valueDelta -= 8; coachKey = `coach_r1_lowclarity`; }

                summaryKey = (d.layer === this.TRUE_LAYER && d.exposed === this.TRUE_EXPOSED) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Build-buy-partner under the envelope and the imitation clock (Common Error 2).
                spend += this._sourceCost(d.source);
                ds.speed = this._sourceSpeed(d.source);

                switch (d.source) {
                    case `buy`:
                        // Fast enough (9mo, within the imitation window) AND keeps the data relationship.
                        valueDelta += 12; defenseDelta += 6; roiDelta += 10; coachKey = `coach_r2_buy`;
                        break;
                    case `build`:
                        // Full IP & control but 18 months — slower than imitation, and eats the envelope.
                        valueDelta += 8; defenseDelta += 8; roiDelta -= 4; coachKey = `coach_r2_build`;
                        break;
                    case `partner`:
                        // Fastest & cheapest but cedes the data relationship and 35% of upside forever.
                        valueDelta -= 8; defenseDelta -= 12; roiDelta -= 6;
                        ds.revShare = 35; ds.cededData = true; coachKey = `coach_r2_partner`;
                        break;
                }

                // Where to innovate (Common Error 1 again, now with money behind it).
                switch (d.focus) {
                    case `datalayer`: valueDelta += 10; roiDelta += 6; break;
                    case `hardware`: valueDelta -= 12; roiDelta -= 8; coachKey = `coach_r2_focus_hw`; break;
                    case `both`: valueDelta -= 2; roiDelta -= 2; coachKey = `coach_r2_focus_split`; break;
                }

                // Interim move to hold the installed base before the platform is live (deadline).
                spend += d.interim;
                if (d.interim >= 3) { valueDelta += 6; defenseDelta += 3; }
                else if (d.interim <= 0.5) { valueDelta -= 6; coachKey = `coach_r2_nointerim`; }

                summaryKey = (d.source !== `partner` && d.focus === `datalayer`) ? `sum_r2_good` : `sum_r2_weak`;
            } else if (round === 3) {
                // Value-capture architecture: model + isolating mechanism (Common Errors 4, 5, 6).
                switch (d.model) {
                    case `outcome`: valueDelta += 11; roiDelta += 8; coachKey = `coach_r3_outcome`; break;
                    case `subscription`: valueDelta += 8; roiDelta += 5; coachKey = `coach_r3_subscription`; break;
                    case `onetime`: valueDelta -= 10; roiDelta -= 6; coachKey = `coach_r3_onetime`; break;
                }

                // Primary isolating mechanism — match it to a software appropriability regime.
                switch (d.moat) {
                    case `datamoat`:
                        defenseDelta += 16; valueDelta += 3;
                        coachKey = (d.model !== `onetime`) ? `coach_r3_datamoat` : coachKey;
                        break;
                    case `switching`: defenseDelta += 11; valueDelta += 2; coachKey = `coach_r3_switching`; break;
                    case `patents`: defenseDelta -= 6; roiDelta -= 4; coachKey = `coach_r3_patents`; break;
                    case `brand`: defenseDelta -= 8; valueDelta -= 4; coachKey = `coach_r3_brand`; break;
                }

                // Investment in the defensive mechanism — the moat must be funded to compound.
                spend += d.defense;
                if (d.defense >= 6) { defenseDelta += 8; valueDelta += 3; }
                else if (d.defense >= 3) { defenseDelta += 3; }
                else { defenseDelta -= 6; coachKey = `coach_r3_nodefense`; }

                // Align sales incentives to the recurring model (Common Error 4: two models fighting).
                if (d.align >= 60) { valueDelta += 8; roiDelta += 3; }
                else if (d.align <= 25) { valueDelta -= 10; roiDelta -= 4; coachKey = `coach_r3_misaligned`; }

                summaryKey = (d.model !== `onetime` && (d.moat === `datamoat` || d.moat === `switching`)) ? `sum_r3_good` : `sum_r3_weak`;
            } else if (round === 4) {
                // Commit & defend the innovation ROI (Common Error 5: ignore the deadline).
                switch (d.gtm) {
                    case `fast`: valueDelta += 7; roiDelta += 8; defenseDelta += 4; coachKey = `coach_r4_fast`; break;
                    case `credible`: valueDelta += 3; roiDelta += 4; coachKey = `coach_r4_credible`; break;
                    case `late`:
                        // 18-month build, no interim move: top accounts lock to PlantSense.
                        valueDelta -= 14; roiDelta -= 10; ds.baseLost = true; coachKey = `coach_r4_late`;
                        break;
                }

                // Defend the ROI honestly — discount for imitation probability and speed.
                switch (d.roiDefence) {
                    case `adjusted`: roiDelta += 12; coachKey = (d.gtm === `fast`) ? `coach_r4_adjusted` : coachKey; break;
                    case `gross`: roiDelta -= 8; coachKey = `coach_r4_gross`; break;
                    case `vague`: roiDelta -= 4; coachKey = `coach_r4_vague`; break;
                }

                // The board's central challenge: what stops PlantSense.
                switch (d.answer) {
                    case `moat`: defenseDelta += 12; valueDelta += 4; coachKey = (d.gtm === `fast` && d.roiDefence === `adjusted`) ? `coach_r4_answer_moat` : coachKey; break;
                    case `patent`: defenseDelta -= 4; coachKey = `coach_r4_answer_patent`; break;
                    case `speed`: defenseDelta -= 8; coachKey = `coach_r4_answer_speed`; break;
                    case `hope`: defenseDelta -= 10; valueDelta -= 4; coachKey = `coach_r4_answer_hope`; break;
                }

                // Conviction nudges ROI.
                roiDelta += Math.round((d.conviction - 60) / 8);

                summaryKey = (d.gtm === `fast` && d.roiDefence === `adjusted` && d.answer === `moat`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // Resource accounting (EUR M against the 40M envelope).
            ds.budgetUsed = Math.round((ds.budgetUsed + spend) * 10) / 10;
            if (ds.budgetUsed > this.BUDGET_CAP + 0.001) ds.overBudget = true;

            // Ceded-data revenue share permanently caps how much value can be captured (partner path).
            if (ds.cededData) valueDelta = Math.round(valueDelta * (1 - ds.revShare / 100));
            // A lost installed base in the final round drags value and defensibility down hard.
            if (ds.baseLost) { valueDelta -= 6; defenseDelta -= 6; }

            ds.value = Math.max(0, Math.min(100, ds.value + valueDelta));
            ds.defense = Math.max(0, Math.min(100, ds.defense + defenseDelta));
            // ROI is gated by defensibility: returns you cannot defend are not real returns.
            const defenseGate = 0.6 + 0.4 * (ds.defense / 100);
            ds.roi = Math.max(0, Math.min(100, ds.roi + roiDelta * defenseGate));

            ds.valueHistory.push(Math.round(ds.value));
            ds.defenseHistory.push(Math.round(ds.defense));
            ds.roiHistory.push(Math.round(ds.roi));

            // v1.1.0: publish composite (0-100) to the reporting/grading layer every period.
            ds.performance = { overallScore: this._composite(ds) };

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            ds.coachMessages.push(coachMsg);
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            return {
                period: state.currentPeriod,
                value: Math.round(ds.value),
                valueDelta: Math.round(valueDelta),
                defense: Math.round(ds.defense),
                defenseDelta: Math.round(defenseDelta),
                roi: Math.round(ds.roi),
                roiDelta: Math.round(roiDelta),
                speed: ds.speed,
                budgetUsed: ds.budgetUsed,
                overBudget: ds.overBudget,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        setupUI(uiManager) {
