                    card.classList.toggle(`valuesim-value-target`, Number(v) >= this.TARGET_VALUE);
                    card.classList.toggle(`valuesim-value-fail`, Number(v) < this.TARGET_VALUE);
                }
                return Math.round(Number(v));
            });
            uiManager.bind(`defenseDisplay`, `domainState.defense`, (v) => Math.round(Number(v)));
            uiManager.bind(`roiDisplay`, `domainState.roi`, (v) => Math.round(Number(v)));
