                const card = document.querySelector(`.valuesim-card-speed`);
                if (card) {
                    card.classList.toggle(`valuesim-speed-late`, n >= 15);
                    card.classList.toggle(`valuesim-speed-fast`, n > 0 && n <= 9);
                }
                if (!n) return `—`;
                return n + ` ` + window.mySimulation.t(`unit_months`);
            });
            uiManager.bind(`budgetDisplay`, `domainState.budgetUsed`, (v) => {
                const card = document.querySelector(`.valuesim-budget-bar`);
                if (card) card.classList.toggle(`valuesim-budget-over`, Number(v) > this.BUDGET_CAP + 0.001);
                return this._fmtBudget(Number(v));
            });

            // Clarity slider readout.
            const clar = document.getElementById(`clarityInput`);
            const clarReadout = document.getElementById(`clarityReadout`);
            if (clar && clarReadout) {
                clarReadout.textContent = clar.value;
                clar.addEventListener(`input`, function() { clarReadout.textContent = clar.value; });
            }

            // Align slider readout.
            const al = document.getElementById(`alignInput`);
            const alReadout = document.getElementById(`alignReadout`);
            if (al && alReadout) {
                alReadout.textContent = al.value;
                al.addEventListener(`input`, function() { alReadout.textContent = al.value; });
            }
        }

        _fmtBudget(v) {
            const es = (window.mySimulation && window.mySimulation.language === `es`);
            const round = Math.round(v * 10) / 10;
            const num = (round % 1 === 0) ? String(round) : (es ? String(round).replace(`.`, `,`) : String(round));
            const cap = `40`;
            // EN: "€28M / €40M"  ·  ES: "28 M€ / 40 M€"
            return es ? (num + ` M€ / ` + cap + ` M€`) : (`€` + num + `M / €` + cap + `M`);
        }

