        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.valueHistory.map((_, i) => (i === 0 ? window.mySimulation.t(`chart_start`) : `R` + i));
            return {
                valueChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.valueHistory },
                        { data: ds.defenseHistory },
                        { data: ds.roiHistory }
                    ]
                }
            };
        }

        // Composite (0-100) VERBATIM from v1.0.0 getPerformanceSummary; written to
        // domainState.performance.overallScore each period for the reporting/grading layer.
        _composite(ds) {
            var value = Math.round(ds.value || 0);
            var defense = Math.round(ds.defense || 0);
            var roi = Math.round(ds.roi || 0);
            return Math.round(value * 0.4 + defense * 0.35 + roi * 0.25);
        }

        _cl(key, fallback) {
            try {
                if (window.mySimulation && typeof window.mySimulation.t === 'function') {
                    var v = window.mySimulation.t(key);
                    if (v && v !== key) return v;
                }
            } catch (e) {}
            return fallback;
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const value = Math.round(ds.value);
            const defense = Math.round(ds.defense);
            const roi = Math.round(ds.roi);

            const hitTarget = value >= this.TARGET_VALUE;
            const defendable = defense >= 60;
            const composite = this._composite(ds);

            const T = (window.mySimulation && typeof window.mySimulation.t === 'function')
                ? function(k, v) { return window.mySimulation.t(k, v); }
                : function(k) { return k; };
            let performanceKey = `grade_leaked`;
            if (hitTarget && defendable && composite >= 72) performanceKey = `grade_captured`;
            else if (hitTarget && defendable) performanceKey = `grade_tight`;
            else if (hitTarget && !defendable) performanceKey = `grade_undefended`;
            else if (value > this.START_VALUE + 18) performanceKey = `grade_exposed`;
            const performance = T(performanceKey);

            const insights = [];
            if (hitTarget && defendable) insights.push(window.mySimulation.t(`insight_captured`));
            else if (hitTarget && !defendable) insights.push(window.mySimulation.t(`insight_undefended`));
            else insights.push(window.mySimulation.t(`insight_short`));

            if (ds.cededData) insights.push(window.mySimulation.t(`insight_ceded`));
            if (ds.baseLost) insights.push(window.mySimulation.t(`insight_baselost`));
            if (defense < 45) insights.push(window.mySimulation.t(`insight_imitable`));
            if (ds.overBudget) insights.push(window.mySimulation.t(`insight_overbudget`));
            if (hitTarget && defendable && roi >= 60) insights.push(window.mySimulation.t(`insight_roi`));

            return {
                value: value,
                defense: defense,
                roi: roi,
                hitTarget: hitTarget,
                defendable: defendable,
                composite: composite,
                overallScore: composite,
                totalScore: composite,
                performanceKey: performanceKey,
                cededData: ds.cededData,
                baseLost: ds.baseLost,
                performance: performance,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            var T = (window.mySimulation && typeof window.mySimulation.t === 'function')
                ? function(k, v) { return window.mySimulation.t(k, v); }
                : function(k) { return k; };
            var s = summary || {};
            var score = (typeof s.overallScore === 'number') ? s.overallScore
                : (typeof s.composite === 'number' ? s.composite : 0);
            var grade = s.performance || (s.performanceKey ? T(s.performanceKey) : '');
            var ok = !!(s.hitTarget && s.defendable);
            var badge = ok
                ? '<span class="valuesim-cm-badge valuesim-cm-yes">' + T('cm_met') + '</span>'
                : '<span class="valuesim-cm-badge valuesim-cm-no">' + T('cm_missed') + '</span>';
            var failBadge = (s.cededData || s.baseLost)
                ? '<span class="valuesim-cm-badge valuesim-cm-warn">' + T('cm_failstate_badge') + '</span>'
                : '';
            var insights = Array.isArray(s.insights) ? s.insights : [];
            var items = insights.map(function(t) { return '<li>' + t + '</li>'; }).join('');
            var metrics = ''
                + '<div class="valuesim-cm-metric"><span class="valuesim-cm-mv">' + Math.round(s.value || 0) + '</span><span class="valuesim-cm-ml">' + T('cm_m_value') + '</span></div>'
                + '<div class="valuesim-cm-metric"><span class="valuesim-cm-mv">' + Math.round(s.defense || 0) + '</span><span class="valuesim-cm-ml">' + T('cm_m_defense') + '</span></div>'
                + '<div class="valuesim-cm-metric"><span class="valuesim-cm-mv">' + Math.round(s.roi || 0) + '</span><span class="valuesim-cm-ml">' + T('cm_m_roi') + '</span></div>';
            return ''
                + '<div class="valuesim-completion">'
                +   '<div class="valuesim-cm-head">'
                +     '<div class="valuesim-cm-score">' + score + '<span class="valuesim-cm-score-max">/100</span></div>'
                +     '<div class="valuesim-cm-grade">' + grade + ' ' + badge + failBadge + '</div>'
                +   '</div>'
                +   '<div class="valuesim-cm-metrics">' + metrics + '</div>'
                +   '<div class="valuesim-cm-insights-title">' + T('cm_debrief') + '</div>'
                +   '<ul class="valuesim-cm-insights">' + items + '</ul>'
                + '</div>';
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.cededData && state.currentPeriod >= 2) return window.mySimulation.t(`hint_ceded`);
            if (ds.defense < 35 && state.currentPeriod >= 2) return window.mySimulation.t(`hint_defense`);
            if (ds.value < 30 && state.currentPeriod >= 2) return window.mySimulation.t(`hint_value`);
            if (state.currentPeriod >= 3 && ds.value < 50) return window.mySimulation.t(`hint_behind`);
            if (ds.value >= this.TARGET_VALUE && ds.defense >= 60) return window.mySimulation.t(`hint_strong`);
            return null;
        }

